namespace Tests;
public class CmsAdminTests(ApiFactory f):ApiTest(f)
{
    [Fact]public async Task Cms_pages_defaults_save_rename_conflict_publish_and_atomic_audit()
    {
        var admin=await Admin();var support=await Staff(admin,"cmssupport@example.test","support");Assert.Equal(403,(await support.Get("/api/admin/storefront/pages")).Status);var r=await admin.Get("/api/admin/storefront/pages");Assert.True(r.Status==200,r.ToString());Assert.NotEmpty(r.Json.AsArray());Assert.All(r.Json.AsArray(),x=>Assert.False(x!["saved"]!.GetValue<bool>()));var defaultSlug=r.Json[0]!["slug"]!.GetValue<string>();
        r=await admin.Put("/api/admin/storefront/pages/synthetic-page",new{slug="synthetic-page",title="Synthetic Page",body="# Synthetic body",meta_description="Synthetic description"});Assert.Equal(200,r.Status);Assert.Equal(200,(await admin.Get("/api/pages/synthetic-page")).Status);Assert.Equal(1,await ApiFactory.DbScalarAsync<long>("SELECT COUNT(*) FROM audit_logs WHERE action='storefront.page'"));
        Assert.Equal(200,(await admin.Put("/api/admin/storefront/pages/synthetic-page",new{slug="renamed-page",title="Renamed Page",body="Private draft",is_published=false})).Status);Assert.Equal(404,(await admin.Get("/api/pages/synthetic-page")).Status);Assert.Equal(404,(await admin.Get("/api/pages/renamed-page")).Status);
        Assert.Equal(200,(await admin.Put("/api/admin/storefront/pages/another-page",new{slug="another-page",title="Another Page",body=""})).Status);Assert.Equal("slug_taken",(await admin.Put("/api/admin/storefront/pages/renamed-page",new{slug="another-page",title="Conflict Page",body=""})).ErrorCode);
        await ApiFactory.DbExecAsync("CREATE TRIGGER synthetic_cms_fail BEFORE INSERT ON audit_logs FOR EACH ROW BEGIN IF NEW.action='storefront.page' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic CMS rollback'; END IF; END");try{Assert.Equal(500,(await admin.Put("/api/admin/storefront/pages/renamed-page",new{slug="renamed-page",title="Must roll back",body="bad"})).Status);Assert.Equal("Renamed Page",await ApiFactory.DbScalarAsync<string>("SELECT title FROM cms_pages WHERE slug='renamed-page'"));}finally{await ApiFactory.DbExecAsync("DROP TRIGGER synthetic_cms_fail");}
        Assert.Equal(422,(await admin.Put("/api/admin/storefront/pages/bad",new{slug="UPPER",title="Bad",body=""})).Status);Assert.Equal(422,(await admin.Put("/api/admin/storefront/pages/bad",new{slug="valid-slug",title="Bad"})).Status);
        Assert.Equal(200,(await admin.Delete("/api/admin/storefront/pages/renamed-page")).Status);Assert.Equal(200,(await admin.Delete("/api/admin/storefront/pages/renamed-page")).Status);Assert.Equal(0,await ApiFactory.DbScalarAsync<long>("SELECT COUNT(*) FROM cms_pages WHERE slug='renamed-page'"));
        Assert.Equal(200,(await admin.Put("/api/admin/storefront/pages/"+defaultSlug,new{slug=defaultSlug,title="Synthetic Default Override",body="Replacement"})).Status);r=await admin.Get("/api/admin/storefront/pages");Assert.True(r.Json.AsArray().Single(x=>x!["slug"]!.GetValue<string>()==defaultSlug)!["saved"]!.GetValue<bool>());await admin.Delete("/api/admin/storefront/pages/"+defaultSlug);r=await admin.Get("/api/admin/storefront/pages");Assert.False(r.Json.AsArray().Single(x=>x!["slug"]!.GetValue<string>()==defaultSlug)!["saved"]!.GetValue<bool>());
    }
}
